code.source:
#include <iostream>
#include <memory>
using namespace std;

int main() {
    unique_ptr<int> p = make_unique<int>(5);
    cout << *p << endl;
    *p = 8;
    cout << *p << endl;
    return 0;
}

#include <iostream>
#include <memory>
#include <utility>
using namespace std;

int main() {
    unique_ptr<int> a = make_unique<int>(5);
    unique_ptr<int> b = move(a);
    cout << (a == nullptr) << endl;
    cout << *b << endl;
    return 0;
}

